```rust
#[derive(Debug, thiserror::Error)]
pub enum ResolutionError {
    #[error("invalid resolver configuration: {0}")]
    InvalidConfiguration(String),

    #[error("session_id is required")]
    MissingSessionId,

    #[error("session routing registry is missing: {path}")]
    RegistryMissing { path: PathBuf },

    #[error("session routing registry is malformed: {path}: {source}")]
    RegistryMalformed { path: PathBuf, source: serde_json::Error },

    #[error("no routing entry exists for session '{session_id}'")]
    RegistryEntryMissing { session_id: String },

    #[error("routing entry for session '{session_id}' points to missing worktree '{path}'")]
    RegistryWorktreeMissing { session_id: String, path: PathBuf },

    #[error("routing entry for session '{session_id}' escapes repository root '{repository}'")]
    RegistryWorktreeOutsideRepository {
        session_id: String,
        repository: PathBuf,
    },

    #[error("session '{session_id}' record does not match registry worktree")]
    RegistrySessionMismatch { session_id: String },

    #[error("session '{session_id}' has non-active worktree status '{status:?}'")]
    InactiveSessionWorktree {
        session_id: String,
        status: session_api::SessionWorktreeStatus,
    },

    #[error("relative workspace path '{path}' is absolute")]
    AbsoluteRelativeWorkspace { path: PathBuf },

    #[error("relative workspace path '{path}' escapes worktree '{worktree}'")]
    RelativeWorkspaceEscapesWorktree { path: PathBuf, worktree: PathBuf },

    #[error("main checkout mutation is blocked: '{target}'")]
    MainCheckoutMutationBlocked { target: PathBuf },

    #[error(
        "workspace selector 'default' for session '{session_id}' is unanchored; \
