        return Ok(self.index_root.clone());
    }
    // Resolve from caller selector.
}
```

Replace the server-local resolver with the shared resolver:

```rust
fn resolve_workspace_root(
    &self,
    session_id: &str,
    relative_workspace: Option<&str>,
) -> Result<ResolvedWorkspace, McpError> {
    self.workspace_resolver
        .resolve(ResolveRequest {
            session_id,
            relative_workspace: relative_workspace.map(Path::new),
            store_dir: ticket_api::workspace::TICKET_INDEX_DIR,
        })
        .map_err(|error| McpError::invalid_params(error.to_string(), None))
